Clase Empleado
    Privado Definir salario Como Entero;

    Metodo Constructor(unSalario Como Entero)
        Este.salario <- unSalario;
    FinMetodo

    Publico Metodo Salario() Como Entero
        Retornar Este.salario;
    FinMetodo

    Publico Metodo Bono() Como Real
        Retornar Este.salario * 0.1;
    FinMetodo
FinClase

Clase Gerente Hereda De Empleado
    Metodo Constructor(unSalario Como Entero)
        Super.Constructor(unSalario);
    FinMetodo

    Publico Metodo Bono() Como Real
        Retornar Este.Salario() * 0.2;
    FinMetodo
FinClase

Proceso CalcularBono
    Definir salario Como Entero;
    Definir gerente Como Gerente;
    Leer salario;
    gerente <- Nuevo Gerente(salario);
    Escribir gerente.Bono();
FinProceso
